};
```

Ticket.cpp:
```cpp
#include "Ticket.h"
#include "Show.h"

Ticket::Ticket(const Show &show, int row, int seat) {
    if (row >= 1 && row <= show.getNumberOfRows() && seat >= 1 && seat <= show.getNumberOfSeats()) {
        this->row = row;
        this->seat = seat;
    } else {
        // Set default or invalid values or throw an exception
        this->row = -1;
        this->seat = -1;
    }
}
```

* Approach 2: Use a dedicated function in the Ticket class.

Ticket.h:
```cpp
