#include "Ticket.h"
#include "Show.h"

void Ticket::assignSeat(const Show &show, int row, int seat) {
    if (row >= 1 && row <= show.getNumberOfRows() && seat >= 1 && seat <= show.getNumberOfSeats()) {
        this->row = row;
        this->seat = seat;
    } else {
        // Set default or invalid values or throw an exception
        this->row = -1;
        this->seat = -1;
    }
}
```

To assign a seat in the Ticket class with either approach, you would create a Show object and a Ticket object, then pass the Show object to the Ticket constructor or call the Ticket::assignSeat method:

```cpp
